-- generated by storm; review before applying
-- 3 step(s)

CREATE TABLE "scorings" (
    "id" text NOT NULL,
    "create_time" timestamptz NOT NULL,
    "name" text NOT NULL,
    "team_id" text,
    "model_id" text NOT NULL,
    "dataset_id" text DEFAULT ''::text NOT NULL,
    "driver" text DEFAULT ''::text NOT NULL,
    "dsn" text DEFAULT ''::text NOT NULL,
    "source_query" text DEFAULT ''::text NOT NULL,
    "status" int4 NOT NULL,
    "error" text DEFAULT ''::text NOT NULL,
    "rows" int8 DEFAULT 0 NOT NULL,
    "done" int8 DEFAULT 0 NOT NULL,
    "failed" int8 DEFAULT 0 NOT NULL,
    "columns" text[] DEFAULT '{}'::text[] NOT NULL,
    "result_bytes" int8 DEFAULT 0 NOT NULL,
    "version_id" text DEFAULT ''::text NOT NULL,
    "created_by" text DEFAULT ''::text NOT NULL,
    "start_time" timestamptz,
    "end_time" timestamptz,
    "repeat_seconds" int8 DEFAULT 0 NOT NULL,
    "next_run" timestamptz,
    "runs" int8 DEFAULT 0 NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_scorings_length_name_between_1_and_100" CHECK ((length(name) >= 1) AND (length(name) <= 100)),
    CONSTRAINT "ck_scorings_rows_0_and_done_0_and_failed_0_and_repeat_seconds_0" CHECK ((rows >= 0) AND (done >= 0) AND (failed >= 0) AND (repeat_seconds >= 0)),
    CONSTRAINT "ck_scorings_status_between_1_and_5" CHECK ((status >= 1) AND (status <= 5))
);
CREATE INDEX "ix_scorings_model_id" ON "scorings" ("model_id");
CREATE INDEX "ix_scorings_next_run_id" ON "scorings" ("next_run", "id") WHERE repeat_seconds > 0;
CREATE INDEX "ix_scorings_status_create_time_id" ON "scorings" ("status", "create_time", "id");
CREATE INDEX "ix_scorings_team_id_create_time_id" ON "scorings" ("team_id", "create_time" DESC, "id" DESC);
ALTER TABLE "scorings" ADD CONSTRAINT "fk_scorings_model_id" FOREIGN KEY ("model_id") REFERENCES "models" ("id") ON DELETE CASCADE;
ALTER TABLE "scorings" ADD CONSTRAINT "fk_scorings_team_id" FOREIGN KEY ("team_id") REFERENCES "teams" ("id");
